#include <ios>
#include <sstream>
#include <locale>
#include <cassert>
#include <type_traits>
#include <utility>
struct IOS : std::ios {
    explicit IOS(std::streambuf *buffer) { init(buffer); }
    void exchange(IOS &other) { swap(other); }
    void transfer(IOS &other) { move(other); }
    void replace(std::streambuf *buffer) { set_rdbuf(buffer); }
};
struct Duplex : std::iostream {
    explicit Duplex(std::streambuf *buffer) : std::iostream(buffer) {}
    void assign(Duplex &&other) { std::iostream::operator=(std::move(other)); }
    void exchange(Duplex &other) { std::iostream::swap(other); }
};
const int slot = std::ios_base::xalloc();
void callback(std::ios_base::event event, std::ios_base &stream, int index) {
    if (event == std::ios_base::imbue_event)
        ++*static_cast<int *>(stream.pword(index));
}
int main() {
    std::stringbuf buffer;
    IOS state{&buffer}, other{&buffer};
    state.exchange(other);
    state.transfer(other);
    state.replace(&buffer);
    assert(state.widen('A') == L'A' && state.narrow('A', '?') == 'A');
    state.imbue(std::locale::classic());
    state.setf(std::ios::hex, std::ios::basefield);
    auto flags = state.flags();
    assert(flags & std::ios::hex);
    state.unsetf(std::ios::basefield);
    std::ios_base::iostate bits = std::ios::goodbit;
    (void)bits;
    std::ios_base::Init init;
    int events = 0;
    state.pword(slot) = &events;
    state.register_callback(callback, slot);
    state.imbue(std::locale::classic());
    assert(events > 0);
    std::istringstream input{"42"};
    int number{};
    input >> number;
    assert(number == 42);
    std::ostringstream output;
    output << number;
    assert(output.str() == "42");
    Duplex duplex{&buffer}, second{&buffer};
    duplex << "abc";
    second.assign(std::move(duplex));
    second.exchange(duplex);
    static_assert(!std::is_copy_assignable<std::ios_base>::value,
        "ios_base is not copy assignable");
}
